{
  "id": 18,
  "knowledge": "Planet-Star Mass Ratio",
  "description": "Calculates the ratio of a planet's mass to its host star's mass.",
  "definition": "The mass ratio ($q$) is: $q = \\frac{M_p}{M_{\\star}}$, where $M_p$ is the planet's mass and $M_{\\star}$ is the star's mass. Both must be in the same units."
}

{
  "id": 24,
  "knowledge": "Super-Earth",
  "description": "A class of planets with masses higher than Earth's but substantially below those of the solar system's ice giants.",
  "definition": "A planet that is likely a Rocky Planet and has a mass between 1 and 10 Earth masses. This depends on the Planet Mass in Earth Units."
}

{
  "id": 21,
  "knowledge": "Rocky Planet",
  "description": "A planet composed primarily of rock or metals, with a solid surface.",
  "definition": "A planet with a bulk density greater than 3 g/cm\u00b3."
}

{
  "id": 19,
  "knowledge": "Gravitational Parameter (\u03bc)",
  "description": "Calculates the standard gravitational parameter for a star, a constant used in orbital mechanics.",
  "definition": "The standard gravitational parameter is $\\mu = G M_{\\star}$, where G is the gravitational constant and $M_{\\star}$ is the mass of the star."
}

{
  "id": 16,
  "knowledge": "Mass-Radius Relationship",
  "description": "A simple ratio to compare a planet's mass and size.",
  "definition": "A basic mass-radius ratio ($MRR$) can be expressed as: $MRR = \\frac{M_E}{R_E}$, which depends on the Planet Mass in Earth Units and Planet Radius in Earth Units."
}

{
  "id": 10,
  "knowledge": "Planet Escape Velocity",
  "description": "Calculates the minimum speed needed for an object to escape a planet's gravitational pull.",
  "definition": "The escape velocity ($v_e$) is calculated as: $v_e = \\sqrt{\\frac{2GM_p}{R_p}}$, where $M_p$ and $R_p$ are the planet's mass and radius, and G is the gravitational constant. The calculation depends on Planet Mass in Earth Units and Planet Radius in Earth Units, converted to standard units."
}

{
  "id": 43,
  "knowledge": "Stellar Mass Value",
  "description": "Illustrates the value for a star's mass.",
  "definition": "Measured in solar masses ($M_{\\odot}$), where 1 is the mass of our Sun. Most known host stars range from low-mass red dwarfs (~0.1 $M_{\\odot}$) to stars several times more massive than the Sun."
}
